package com.bank.api.controller;

import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
import java.math.BigDecimal;
import java.util.Map;

// THE API: the language-neutral contract. Any client in any language calls this.
@RestController
@RequestMapping("/api/v1/transfers")
public class TransferController {

    @PostMapping
    public ResponseEntity<Map<String, String>> create(
            @RequestHeader("Authorization") String auth,
            @RequestHeader(value = "Idempotency-Key", required = false) String idemKey,
            @RequestBody Map<String, Object> body) {

        if (!auth.startsWith("Bearer ")) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED)
                    .body(Map.of("error", "MISSING_TOKEN"));
        }
        BigDecimal amount = new BigDecimal(body.get("amount").toString());
        // 201 with a transfer id — the documented success contract.
        return ResponseEntity.status(HttpStatus.CREATED)
                .body(Map.of("transferId", "TXF-001", "status", "COMPLETED"));
    }
}
