package com.bank.sdk;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import java.net.URI;
import java.net.http.*;
import java.util.UUID;

// THE SDK: wraps the API. Handles auth, serialization, retries, idempotency,
// and maps errors to exceptions — so the partner calls one typed method.
public class BankClient {

    private static final Logger log = LoggerFactory.getLogger(BankClient.class);
    private final String baseUrl;
    private final String token;
    private final HttpClient http = HttpClient.newHttpClient();
    private final ObjectMapper mapper = new ObjectMapper();

    public BankClient(String baseUrl, String token) {
        this.baseUrl = baseUrl;
        this.token = token;
    }

    public TransferResult createTransfer(TransferRequest request) {
        String idempotencyKey = UUID.randomUUID().toString();  // safe retries
        int attempt = 0;
        while (true) {
            attempt++;
            try {
                String json = mapper.writeValueAsString(request);          // serialize
                HttpRequest req = HttpRequest.newBuilder()
                        .uri(URI.create(baseUrl + "/api/v1/transfers"))
                        .header("Authorization", "Bearer " + token)        // auth handled
                        .header("Content-Type", "application/json")
                        .header("Idempotency-Key", idempotencyKey)
                        .POST(HttpRequest.BodyPublishers.ofString(json))
                        .build();

                HttpResponse<String> resp = http.send(req, HttpResponse.BodyHandlers.ofString());
                if (resp.statusCode() == 201) {
                    var node = mapper.readTree(resp.body());               // deserialize
                    return new TransferResult(node.get("transferId").asText(),
                                              node.get("status").asText());
                }
                if (resp.statusCode() == 503 && attempt < 3) {
                    long backoff = (long) Math.pow(2, attempt) * 100;      // retry w/ backoff
                    log.warn("Transient 503, retrying in {}ms (attempt {})", backoff, attempt);
                    Thread.sleep(backoff);
                    continue;
                }
                throw new TransferException(resp.statusCode(), resp.body()); // map to exception
            } catch (TransferException te) {
                throw te;
            } catch (Exception e) {
                throw new TransferException(0, "SDK call failed: " + e.getMessage());
            }
        }
    }
}
